class StringBuffer {
private:
    char* buffer;
    size_t size;
public:
    StringBuffer(const char* str) {
        size = strlen(str);
        buffer = new char[size + 1];
        strcpy(buffer, str);
    }
    ~StringBuffer() { delete[] buffer; }
    void append(const char* str) {
        size_t newSize = size + strlen(str);
        char* newBuffer = new char[newSize + 1];
        strcpy(newBuffer, buffer);
        strcat(newBuffer, str);
        buffer = newBuffer;
        size = newSize;
    }
    const char* get() const { return buffer; }
};

int main() {
    StringBuffer sb("hello");
    StringBuffer sb2 = sb;
    sb.append(" world");
    std::cout << sb2.get() << std::endl;
}

